def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    opp_pressures = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                b = float(bid)
                prev_bids.append(b)
                req = float(opp.get('water_requirement', WATER_REQ))
                obudget = float(opp.get('budget', 0.0))
                pressure = 0.0
                if req > 0:
                    pressure += min(1.0, supply / req)
                pressure += min(2.0, b / max(1.0, obudget + b))
                opp_pressures.append((b, pressure))

    if not alive_opponents:
        return min(budget, 18.0)

    units = supply / WATER_REQ
    tight = units < 1.45
    roomy = units > 1.75

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    dangerous_opp_bid = 0.0
    if opp_pressures:
        opp_pressures.sort(key=lambda x: (x[1], x[0]), reverse=True)
        dangerous_opp_bid = opp_pressures[int(0)][0]

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water >= 2:
        urgency += 1.0
    elif no_water == 1:
        urgency += 0.45
    if tight:
        urgency += 0.55
    elif roomy:
        urgency -= 0.15

    days_left = max(0, 10 - day)
    reserve_target = max(0.0, days_left * DAILY_SALARY * 0.42)
    spendable = max(0.0, budget - reserve_target)

    if urgency >= 1.6:
        target = max(62.0, dangerous_opp_bid + 3.0, highest_prev + 1.5)
    elif urgency >= 0.9:
        target = max(44.0, avg_prev * 0.72, dangerous_opp_bid * 0.82)
    else:
        if roomy:
            target = max(10.0, avg_prev * 0.18)
        else:
            target = max(18.0, avg_prev * 0.35)

    if budget < DAILY_SALARY * 0.9:
        target *= 0.82
    if spendable < target and urgency < 1.6:
        target = max(8.0, min(target, spendable + DAILY_SALARY * 0.18))

    if hp <= 1 or no_water >= 3:
        target = max(target, min(budget, highest_prev + 6.0, 95.0))

    bid = min(budget, max(0.0, target))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    if not alive:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids to infer aggression level
    prev_bids = []
    for o in alive:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Aggression estimate: if bids were large relative to our daily salary, opponents are likely bidding to secure
    pressure = 0.0
    if highest_prev_bid > 0:
        pressure = min(1.0, highest_prev_bid / (DAILY_SALARY * 1.6))

    # Our urgency: low hp or already missing water increases urgency
    urgency = 0.0
    if hp <= 1.0:
        urgency = 1.0
    elif hp <= 3.0:
        urgency = 0.8
    elif hp <= 5.0:
        urgency = 0.6
    else:
        urgency = 0.4

    if no_water_days >= 2:
        urgency = min(1.0, urgency + 0.2)

    # Supply factor: with lower supply, competition should be higher
    supply_factor = 0.5
    if supply <= (MIN_SUPPLY + 0.5):
        supply_factor = 0.95
    elif supply <= ((MIN_SUPPLY + MAX_SUPPLY) / 2.0):
        supply_factor = 0.75
    else:
        supply_factor = 0.6

    # Target bid: try to beat the likely clearing price without overmatching
    # Use second-highest as a proxy for where we need to be, but cap by our budget and a safety multiplier.
    base = DAILY_SALARY * (0.35 + 0.35 * urgency) * supply_factor

    # If yesterday highest was extreme, we should bid closer to it; otherwise bid near second-highest.
    if highest_prev_bid >= DAILY_SALARY * 1.2:
        target = max(base, second_prev_bid + 2.0)
        target = min(target, highest_prev_bid * (0.85 + 0.1 * pressure))
    else:
        target = max(base, second_prev_bid + 1.0)
        target = min(target, highest_prev_bid * 0.7 + base)

    # Convert to a practical bid with integer cents-like granularity (optional)
    target = float(target)

    # Budget safety: never bid more than we can afford; also avoid bankrupting unless very urgent
    max_affordable = budget
    if urgency < 0.8:
        max_affordable = min(max_affordable, DAILY_SALARY * (0.9 + 0.1 * pressure))

    bid = min(target, max_affordable)

    # If bid is too low to matter in high pressure, floor it
    if pressure > 0.6 and urgency > 0.5:
        bid = max(bid, DAILY_SALARY * 0.55)

    # If extremely urgent, allow higher bid
    if urgency >= 0.9:
        bid = max(bid, DAILY_SALARY * 0.85)
        bid = min(bid, budget)

    # Final clamp
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        target = min(my_status['budget'], max(DAILY_SALARY * 0.4, avg_prev * 1.05))
        return target

    return min(my_status['budget'], DAILY_SALARY * 0.5)
